INSERT INTO public.opportunities (title, company_name, employment_type, location, mode, stipend_or_salary, experience_required, skills_required, description, application_link, deadline, is_active, department, experience_level, salary_range_min, salary_range_max, status, posted_date, requirements, responsibilities, benefits, applications_count, messages_count, views_count, job_title, schedule_note, recruiter_id, created_by, created_by_uuid, organization_id)
SELECT s.title, s.company_name, s.employment_type, s.location, s.mode, s.stipend_or_salary, s.experience_required, s.skills_required, s.description, s.application_link, s.deadline, s.is_active, s.department, s.experience_level, s.salary_range_min, s.salary_range_max, s.status, s.posted_date, s.requirements, s.responsibilities, s.benefits, s.applications_count, s.messages_count, s.views_count, s.job_title, s.schedule_note,
       owner.recruiter_id,
       owner.created_by_uuid::text,
       owner.created_by_uuid,
       owner.organization_id
FROM seed_rows s
CROSS JOIN owner
WHERE NOT EXISTS (
  SELECT 1
  FROM public.opportunities existing
  WHERE lower(existing.company_name) = lower(s.company_name)
    AND lower(existing.job_title) = lower(s.job_title)
    AND lower(existing.location) = lower(s.location)
    AND COALESCE(existing.application_link, '') = COALESCE(s.application_link, '')
);

-- If this file is rerun after local recruiter/user seeds have been loaded,
-- attach previously inserted tracker opportunities to Krishna without
-- changing ownership of unrelated opportunities.
WITH selected_recruiter AS (
  SELECT r.id AS recruiter_id, r.user_id AS created_by_uuid
  FROM public.recruiters r
  WHERE lower(r.email) IN (lower('krishna@rareminds.in'), lower('visakh@rareminds.in'))
     OR lower(r.name) LIKE '%rareminds%'
  ORDER BY
    CASE lower(r.email)
      WHEN lower('krishna@rareminds.in') THEN 0
      WHEN lower('visakh@rareminds.in') THEN 1
      ELSE 2
    END,
    CASE WHEN COALESCE(r.isactive, TRUE) THEN 0 ELSE 1 END,
    r.createdat NULLS LAST,
    r.id
  LIMIT 1
)
UPDATE public.opportunities o
SET recruiter_id = sr.recruiter_id,
    created_by = sr.created_by_uuid::text,
    created_by_uuid = sr.created_by_uuid,
    organization_id = COALESCE(
      u."organizationId",
      o.organization_id,
      (
        SELECT org.id
        FROM public.organizations org
        WHERE lower(org.name) = lower('Rareminds')
        ORDER BY org.created_at NULLS LAST, org.id
        LIMIT 1
      )
    ),
    updated_at = timezone('utc'::text, now())
FROM selected_recruiter sr
JOIN public.users u ON u.id = sr.created_by_uuid
WHERE position('"source_workbook":"Rareminds_Pan_India_Fresher_Opportunity_Tracker 4.xlsx"' in o.description) > 0;

COMMIT;
